def min_Swaps(s1: str, s2: str) -> int:
    if len(s1) != len(s2):
        raise ValueError("Strings must be of equal length")
    if sorted(s1) != sorted(s2):
        return -1  # impossible if counts of 1s and 0s differ

    # Count positions where s1 has '1' and s2 has '0'
    # Each such mismatch requires one swap with a position where s1 has '0' and s2 has '1'
    mismatches = 0
    for a, b in zip(s1, s2):
        if a == '1' and b == '0':
            mismatches += 1
    return mismatches

# Example test
if __name__ == "__main__":
    assert min_Swaps("1101", "1110") == 1
    print("All tests passed.")
